// ---- carreiras: junta disciplinas, leis e normas extras dos editais listados ----
(function () {
  var porId = {};
  EDITAIS_DATA.forEach(function (e) { porId[e.id] = e; });
  EDITAIS_DATA.forEach(function (c) {
    if (c.tipo !== "carreira" || !c.editais || !c.editais.length) return;
    var membros = c.editais.map(function (id) { return porId[id]; }).filter(Boolean);
    var leis = [], extras = [], disciplinas = [], visto = {};
    membros.forEach(function (e) {
      (e.leis || []).forEach(function (p) {
        var k = "l|" + p[0] + "|" + p[1];
        if (!visto[k]) { visto[k] = true; leis.push(p); }
      });
      (e.extras || []).forEach(function (x) {
        if (!visto["x|" + x]) { visto["x|" + x] = true; extras.push(x); }
      });
      (e.grupos || []).forEach(function (g) {
        (g.disciplinas || []).forEach(function (d) {
          if (!visto["d|" + d]) { visto["d|" + d] = true; disciplinas.push(d); }
        });
      });
    });
    var siglas = membros.map(function (e) { return e.sigla; });
    c.leis = leis;
    c.extras = extras;
    c.grupos = [{ nome: "Disciplinas (união dos editais)", disciplinas: disciplinas }];
    c.cargo = "união dos editais: " + siglas.join(", ");
    c.orgao = "Reúne o conteúdo de " + membros.length + (membros.length === 1 ? " edital" : " editais");
    c.edital = membros.map(function (e) { return e.sigla + ": " + e.titulo; }).join(" · ");
  });
})();

// Deixa os dados visíveis para os outros arquivos do site mesmo quando esta
// página carrega o arquivo com <script type="module"> (nesse modo, "var" não
// cria variável global).
window.EDITAIS_DATA = EDITAIS_DATA;
